/**
 * Small PNG codec plus a Lanczos resampler, so the market icon is generated by
 * TypeScript tooling instead of an external image converter.
 *
 * Only the shapes the branding masters actually use are supported: non
 * interlaced PNG with 8- or 16-bit samples (RGB, RGBA, gray, gray+alpha and
 * palette). Anything else fails loudly rather than producing a wrong icon.
 */
import { deflateSync, inflateSync } from 'node:zlib';

export interface RgbaImage {
  width: number;
  height: number;
  /** Row-major RGBA, 8 bits per channel. */
  data: Uint8Array;
}

const SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
const CHANNELS: Record<number, number> = { 0: 1, 2: 3, 3: 1, 4: 2, 6: 4 };

function paeth(left: number, above: number, upperLeft: number): number {
  const estimate = left + above - upperLeft;
  const toLeft = Math.abs(estimate - left);
  const toAbove = Math.abs(estimate - above);
  const toUpperLeft = Math.abs(estimate - upperLeft);
  if (toLeft <= toAbove && toLeft <= toUpperLeft) return left;
  return toAbove <= toUpperLeft ? above : upperLeft;
}

function checkSignature(input: Buffer): void {
  if (input.length < 8 || !input.subarray(0, 8).equals(SIGNATURE)) throw new Error('Not a PNG file');
}

interface PngHeader {
  width: number;
  height: number;
  bitDepth: number;
  colorType: number;
  interlace: number;
  palette?: Buffer;
  transparency?: Buffer;
}

export function decodePng(input: Buffer): RgbaImage {
  checkSignature(input);
  const header: PngHeader = { width: 0, height: 0, bitDepth: 0, colorType: 0, interlace: 0 };
  const parts: Buffer[] = [];
  let cursor = 8;
  while (cursor + 8 <= input.length) {
    const length = input.readUInt32BE(cursor);
    const type = input.toString('latin1', cursor + 4, cursor + 8);
    const body = input.subarray(cursor + 8, cursor + 8 + length);
    cursor += 12 + length;
    if (type === 'IHDR') {
      header.width = body.readUInt32BE(0);
      header.height = body.readUInt32BE(4);
      header.bitDepth = body.readUInt8(8);
      header.colorType = body.readUInt8(9);
      header.interlace = body.readUInt8(12);
    } else if (type === 'PLTE') header.palette = body;
    else if (type === 'tRNS') header.transparency = body;
    else if (type === 'IDAT') parts.push(body);
    else if (type === 'IEND') break;
  }
  if (!header.width || !header.height) throw new Error('PNG header missing');
  const channels = CHANNELS[header.colorType];
  if (channels === undefined) throw new Error(`Unsupported PNG color type ${header.colorType}`);
  if (header.interlace !== 0) throw new Error('Interlaced PNG is not supported');
  if (header.bitDepth !== 8 && header.bitDepth !== 16) throw new Error(`Unsupported PNG bit depth ${header.bitDepth}`);

  const bytesPerSample = header.bitDepth === 16 ? 2 : 1;
  const pixelBytes = channels * bytesPerSample;
  const stride = header.width * pixelBytes;
  const raw = inflateSync(Buffer.concat(parts));
  if (raw.length < (stride + 1) * header.height) throw new Error('PNG data is truncated');

  const pixels = Buffer.alloc(stride * header.height);
  for (let row = 0; row < header.height; row += 1) {
    const filter = raw.readUInt8(row * (stride + 1));
    const source = row * (stride + 1) + 1;
    const target = row * stride;
    for (let index = 0; index < stride; index += 1) {
      const value = raw.readUInt8(source + index);
      const left = index >= pixelBytes ? pixels.readUInt8(target + index - pixelBytes) : 0;
      const above = row > 0 ? pixels.readUInt8(target + index - stride) : 0;
      const upperLeft = row > 0 && index >= pixelBytes ? pixels.readUInt8(target + index - stride - pixelBytes) : 0;
      let restored: number;
      switch (filter) {
        case 0: restored = value; break;
        case 1: restored = value + left; break;
        case 2: restored = value + above; break;
        case 3: restored = value + ((left + above) >> 1); break;
        case 4: restored = value + paeth(left, above, upperLeft); break;
        default: throw new Error(`Unsupported PNG filter ${filter}`);
      }
      pixels.writeUInt8(restored & 0xff, target + index);
    }
  }

  const data = new Uint8Array(header.width * header.height * 4);
  for (let pixel = 0; pixel < header.width * header.height; pixel += 1) {
    const offset = pixel * pixelBytes;
    const channel = (index: number): number => {
      const at = offset + index * bytesPerSample;
      return header.bitDepth === 16 ? pixels.readUInt8(at) : pixels.readUInt8(at);
    };
    const target = pixel * 4;
    switch (header.colorType) {
      case 0: data[target] = channel(0); data[target + 1] = channel(0); data[target + 2] = channel(0); data[target + 3] = 255; break;
      case 2: data[target] = channel(0); data[target + 1] = channel(1); data[target + 2] = channel(2); data[target + 3] = 255; break;
      case 3: {
        const palette = header.palette;
        if (!palette) throw new Error('Palette PNG without PLTE chunk');
        const index = channel(0) * 3;
        data[target] = palette.readUInt8(index);
        data[target + 1] = palette.readUInt8(index + 1);
        data[target + 2] = palette.readUInt8(index + 2);
        data[target + 3] = header.transparency && header.transparency.length > channel(0)
          ? header.transparency.readUInt8(channel(0)) : 255;
        break;
      }
      case 4: data[target] = channel(0); data[target + 1] = channel(0); data[target + 2] = channel(0); data[target + 3] = channel(1); break;
      default: data[target] = channel(0); data[target + 1] = channel(1); data[target + 2] = channel(2); data[target + 3] = channel(3); break;
    }
  }
  return { width: header.width, height: header.height, data };
}

function chunk(type: string, body: Buffer): Buffer {
  const head = Buffer.alloc(8);
  head.writeUInt32BE(body.length, 0);
  head.write(type, 4, 'latin1');
  const checksum = Buffer.alloc(4);
  checksum.writeUInt32BE(crc32(Buffer.concat([Buffer.from(type, 'latin1'), body])), 0);
  return Buffer.concat([head, body, checksum]);
}

const CRC_TABLE = ((): Uint32Array => {
  const table = new Uint32Array(256);
  for (let index = 0; index < 256; index += 1) {
    let value = index;
    for (let bit = 0; bit < 8; bit += 1) value = (value & 1) !== 0 ? 0xedb88320 ^ (value >>> 1) : value >>> 1;
    table[index] = value >>> 0;
  }
  return table;
})();

export function crc32(bytes: Uint8Array): number {
  let crc = 0xffffffff;
  for (const byte of bytes) crc = CRC_TABLE[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

export function encodePng(image: RgbaImage): Buffer {
  const header = Buffer.alloc(13);
  header.writeUInt32BE(image.width, 0);
  header.writeUInt32BE(image.height, 4);
  header.writeUInt8(8, 8);
  header.writeUInt8(6, 9);
  header.writeUInt8(0, 10);
  header.writeUInt8(0, 11);
  header.writeUInt8(0, 12);
  const stride = image.width * 4;
  const raw = Buffer.alloc((stride + 1) * image.height);
  for (let row = 0; row < image.height; row += 1) {
    raw.writeUInt8(0, row * (stride + 1));
    Buffer.from(image.data.buffer, image.data.byteOffset + row * stride, stride).copy(raw, row * (stride + 1) + 1);
  }
  return Buffer.concat([
    SIGNATURE,
    chunk('IHDR', header),
    chunk('IDAT', deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

interface Contribution {
  start: number;
  weights: Float64Array;
}

function lanczos(value: number, radius: number): number {
  if (value === 0) return 1;
  if (value <= -radius || value >= radius) return 0;
  const scaled = Math.PI * value;
  return (radius * Math.sin(scaled) * Math.sin(scaled / radius)) / (scaled * scaled);
}

function contributions(sourceSize: number, targetSize: number, radius = 3): Contribution[] {
  const scale = targetSize / sourceSize;
  const filterScale = scale < 1 ? 1 / scale : 1;
  const support = radius * filterScale;
  const result: Contribution[] = [];
  for (let index = 0; index < targetSize; index += 1) {
    const center = (index + 0.5) / scale - 0.5;
    const first = Math.max(0, Math.ceil(center - support));
    const last = Math.min(sourceSize - 1, Math.floor(center + support));
    const weights = new Float64Array(Math.max(1, last - first + 1));
    let total = 0;
    for (let sample = first; sample <= last; sample += 1) {
      const weight = lanczos((sample - center) / filterScale, radius);
      weights[sample - first] = weight;
      total += weight;
    }
    if (total === 0) {
      const nearest = Math.min(sourceSize - 1, Math.max(0, Math.round(center)));
      weights.fill(0);
      weights[nearest - first] = 1;
    } else {
      for (let sample = 0; sample < weights.length; sample += 1) weights[sample] /= total;
    }
    result.push({ start: first, weights });
  }
  return result;
}

/**
 * Resize with a Lanczos-3 kernel. Alpha is premultiplied so transparent pixels
 * cannot bleed colour halos into the edges of the icon.
 */
export function resample(image: RgbaImage, width: number, height: number): RgbaImage {
  if (image.width === width && image.height === height) return image;
  const source = new Float32Array(image.width * image.height * 4);
  for (let pixel = 0; pixel < image.width * image.height; pixel += 1) {
    const alpha = image.data[pixel * 4 + 3] / 255;
    source[pixel * 4] = image.data[pixel * 4] * alpha;
    source[pixel * 4 + 1] = image.data[pixel * 4 + 1] * alpha;
    source[pixel * 4 + 2] = image.data[pixel * 4 + 2] * alpha;
    source[pixel * 4 + 3] = image.data[pixel * 4 + 3];
  }

  const horizontal = new Float32Array(width * image.height * 4);
  const columns = contributions(image.width, width);
  for (let y = 0; y < image.height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const column = columns[x];
      let red = 0, green = 0, blue = 0, alpha = 0;
      for (let index = 0; index < column.weights.length; index += 1) {
        const weight = column.weights[index];
        const pixel = (y * image.width + column.start + index) * 4;
        red += source[pixel] * weight;
        green += source[pixel + 1] * weight;
        blue += source[pixel + 2] * weight;
        alpha += source[pixel + 3] * weight;
      }
      const target = (y * width + x) * 4;
      horizontal[target] = red;
      horizontal[target + 1] = green;
      horizontal[target + 2] = blue;
      horizontal[target + 3] = alpha;
    }
  }

  const output = new Uint8Array(width * height * 4);
  const rows = contributions(image.height, height);
  for (let y = 0; y < height; y += 1) {
    const row = rows[y];
    for (let x = 0; x < width; x += 1) {
      let red = 0, green = 0, blue = 0, alpha = 0;
      for (let index = 0; index < row.weights.length; index += 1) {
        const weight = row.weights[index];
        const pixel = ((row.start + index) * width + x) * 4;
        red += horizontal[pixel] * weight;
        green += horizontal[pixel + 1] * weight;
        blue += horizontal[pixel + 2] * weight;
        alpha += horizontal[pixel + 3] * weight;
      }
      const target = (y * width + x) * 4;
      const opacity = Math.min(255, Math.max(0, Math.round(alpha)));
      const unpremultiply = opacity === 0 ? 0 : 255 / opacity;
      output[target] = Math.min(255, Math.round(red * unpremultiply));
      output[target + 1] = Math.min(255, Math.round(green * unpremultiply));
      output[target + 2] = Math.min(255, Math.round(blue * unpremultiply));
      output[target + 3] = opacity;
    }
  }
  return { width, height, data: output };
}

/** Build a multi-resolution .ico: BMP entries up to 128 px, PNG for 256 px. */
export function buildIco(master: RgbaImage, sizes: number[] = [16, 24, 32, 48, 64, 128, 256]): Buffer {
  const images = sizes.map(size => ({ size, image: resample(master, size, size) }));
  const payloads = images.map(({ size, image }) => (size >= 256 ? encodePng(image) : bmpEntry(image)));
  const header = Buffer.alloc(6 + 16 * images.length);
  header.writeUInt16LE(0, 0);
  header.writeUInt16LE(1, 2);
  header.writeUInt16LE(images.length, 4);
  let offset = header.length;
  images.forEach(({ size }, index) => {
    const entry = 6 + 16 * index;
    header.writeUInt8(size >= 256 ? 0 : size, entry);
    header.writeUInt8(size >= 256 ? 0 : size, entry + 1);
    header.writeUInt8(0, entry + 2);
    header.writeUInt8(0, entry + 3);
    header.writeUInt16LE(1, entry + 4);
    header.writeUInt16LE(32, entry + 6);
    header.writeUInt32LE(payloads[index].length, entry + 8);
    header.writeUInt32LE(offset, entry + 12);
    offset += payloads[index].length;
  });
  return Buffer.concat([header, ...payloads]);
}

function bmpEntry(image: RgbaImage): Buffer {
  const { width, height, data } = image;
  const header = Buffer.alloc(40);
  header.writeUInt32LE(40, 0);
  header.writeInt32LE(width, 4);
  header.writeInt32LE(height * 2, 8);
  header.writeUInt16LE(1, 12);
  header.writeUInt16LE(32, 14);
  const pixels = Buffer.alloc(width * height * 4);
  const maskStride = Math.ceil(width / 32) * 4;
  const mask = Buffer.alloc(maskStride * height);
  for (let y = 0; y < height; y += 1) {
    const row = height - 1 - y;
    for (let x = 0; x < width; x += 1) {
      const source = (y * width + x) * 4;
      const target = (row * width + x) * 4;
      pixels[target] = data[source + 2];
      pixels[target + 1] = data[source + 1];
      pixels[target + 2] = data[source];
      pixels[target + 3] = data[source + 3];
      if (data[source + 3] === 0) mask[row * maskStride + (x >> 3)] |= 0x80 >> (x & 7);
    }
  }
  header.writeUInt32LE(pixels.length + mask.length, 20);
  return Buffer.concat([header, pixels, mask]);
}

const ICNS_TYPES: Array<[number, string]> = [
  [16, 'icp4'], [32, 'icp5'], [64, 'icp6'], [128, 'ic07'], [256, 'ic08'], [512, 'ic09'], [1024, 'ic10'],
];

export function buildIcns(master: RgbaImage): Buffer {
  const chunks = ICNS_TYPES.map(([size, type]) => {
    const payload = encodePng(resample(master, size, size));
    const head = Buffer.alloc(8);
    head.write(type, 0, 'latin1');
    head.writeUInt32BE(payload.length + 8, 4);
    return Buffer.concat([head, payload]);
  });
  const body = Buffer.concat(chunks);
  const header = Buffer.alloc(8);
  header.write('icns', 0, 'latin1');
  header.writeUInt32BE(body.length + 8, 4);
  return Buffer.concat([header, body]);
}
